<?php
declare(strict_types=1);

function qa180_settings(App $app,array $user,array $tenant):void {
    $branch=physical_branch_v14($app,$tenant);
    if(is_post()){
        verify_csrf();try {
            qa180_permission($app,$user,'configuracion','configure');$name=mb_substr(trim((string)($_POST['name']??'')),0,150);$email=trim((string)($_POST['email']??''));$tax=trim((string)($_POST['tax_id']??''));$required=isset($_POST['tax_id_required']);$digits=preg_replace('/\D/','',$tax);
            if($name===''||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL)))throw new DomainException('Revisa el nombre y el correo del negocio.');
            if(($required&&$tax==='')||($tax!==''&&(!preg_match('/^[0-9 -]+$/D',$tax)||strlen($digits)<9||strlen($digits)>12)))throw new DomainException('Escribe la cédula física, jurídica o identificación del negocio (9 a 12 dígitos; se permiten guiones).');
            $values=[$name,$email,mb_substr(trim((string)($_POST['phone']??'')),0,40),mb_substr(trim((string)($_POST['whatsapp']??'')),0,40),mb_substr(trim((string)($_POST['address']??'')),0,2000),mb_substr(trim((string)($_POST['business_hours']??'')),0,1000),mb_substr(trim((string)($_POST['map_embed']??'')),0,5000),($_POST['catalog_label']??'')==='Menú'?'Menú':'Catálogo',mb_substr(trim((string)($_POST['offline_message']??'')),0,1000),$tax?:null,$required?1:0];
            $extra=[];foreach(['facebook_url','instagram_url','tiktok_url'] as $key){$link=trim((string)($_POST[$key]??$tenant[$key]??''));if($link!==''&&(!filter_var($link,FILTER_VALIDATE_URL)||!preg_match('~^https?://~i',$link)))throw new DomainException('Usa un enlace http o https válido en redes sociales.');$extra[$key]=$link?:null;}
            $choices=['payment_methods'=>['SINPE Móvil','Efectivo','Tarjeta al recibir','Transferencia'],'delivery_types'=>['delivery','pickup','coordinated']];foreach($choices as $key=>$allowed){if(isset($_POST['more_settings180'])||isset($_POST[$key])){$selected=array_values(array_intersect($allowed,(array)($_POST[$key]??[])));if(!$selected)throw new DomainException('Selecciona al menos un método de pago y una forma de entrega.');$extra[$key]=json_encode($selected,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);}else $extra[$key]=$tenant[$key];}
            $extra['tax_included']=isset($_POST['more_settings180'])?(isset($_POST['tax_included'])?1:0):$tenant['tax_included'];
            $logo=upload_image('logo');$app->db->beginTransaction();$app->one('SELECT id FROM tenants WHERE id=? FOR UPDATE',[$tenant['id']]);
            $app->exec('UPDATE tenants SET name=?,email=?,phone=?,whatsapp=?,address=?,business_hours=?,map_embed=?,catalog_label=?,offline_message=?,tax_id=?,tax_id_required=?'.($logo?',logo=?':'').' WHERE id=?',[...$values,...($logo?[$logo]:[]),$tenant['id']]);
            $app->exec('UPDATE tenants SET facebook_url=?,instagram_url=?,tiktok_url=?,payment_methods=?,delivery_types=?,tax_included=? WHERE id=?',[...array_values($extra),$tenant['id']]);
            if($branch)$app->exec('UPDATE branches SET web_order_acceptance=? WHERE id=? AND tenant_id=?',[(int)(($_POST['web_order_acceptance']??'1')!=='0'),$branch['id'],$tenant['id']]);
            qa180_audit($app,$user,'update_settings','tenant',(int)$tenant['id'],'Actualizó los datos generales, la identificación fiscal y la recepción de pedidos web');$app->db->commit();flash('success','Datos guardados. La identificación se imprime en los nuevos recibos.');
        }catch(Throwable $error){if($app->db->inTransaction())$app->db->rollBack();flash('error',$error instanceof PDOException?'No se guardaron los datos. Revisa la configuración antes de repetir.':$error->getMessage());}
        redirect(url('admin/configuracion'));
    }
    admin_shell_start('Generales',$user,$tenant,'configuracion');echo '<section class="card admin-card"><form method="post" enctype="multipart/form-data">'.csrf_field().pos_hidden_148('more_settings180',1).field('Nombre comercial','name',$tenant['name'],true).'<div class="split">'.field('Correo','email',$tenant['email'],false,'email').field('Teléfono','phone',$tenant['phone']).'</div>'.field('WhatsApp de pedidos','whatsapp',$tenant['whatsapp']).field('Cédula del negocio','tax_id',$tenant['tax_id']??'').'<label><input type="checkbox" name="tax_id_required" '.(!empty($tenant['tax_id_required'])?'checked':'').'> Identificación requerida en los datos del negocio</label><p>Esta identificación se muestra en recibos. Su registro no activa facturación electrónica.</p>'.field('Dirección','address',$tenant['address']).field('Horario','business_hours',$tenant['business_hours']??'').'<label>Mapa de Google (iframe)<textarea class="input" name="map_embed" rows="3">'.e($tenant['map_embed']).'</textarea></label><label>Logo de tu tienda'.(!empty($tenant['logo'])?'<img class="r2-editor-image" src="'.e(public_media_url($tenant['logo'])).'" alt="Logo actual">':'').'<input class="input" type="file" name="logo" accept="image/jpeg,image/png,image/webp"></label><label>Catálogo o menú<select class="input" name="catalog_label"><option>Catálogo</option><option '.($tenant['catalog_label']==='Menú'?'selected':'').'>Menú</option></select></label>'.field('Mensaje al suspender el negocio','offline_message',$tenant['offline_message']);
    foreach(['facebook_url'=>'Facebook','instagram_url'=>'Instagram','tiktok_url'=>'TikTok'] as $key=>$label)echo field($label,$key,$tenant[$key]??'',false,'url');
    foreach(['payment_methods'=>['Métodos de pago',['SINPE Móvil'=>'SINPE Móvil','Efectivo'=>'Efectivo','Tarjeta al recibir'=>'Tarjeta al recibir','Transferencia'=>'Transferencia']], 'delivery_types'=>['Formas de entrega',['delivery'=>'Envío','pickup'=>'Recoger','coordinated'=>'Coordinado']]] as $key=>[$label,$options]){$selected=json_decode((string)$tenant[$key],true)?:array_keys($options);echo '<fieldset><legend>'.$label.'</legend>';foreach($options as $value=>$text)echo '<label><input type="checkbox" name="'.$key.'[]" value="'.e($value).'" '.(in_array($value,$selected,true)?'checked':'').'> '.e($text).'</label>';echo '</fieldset>';}
    echo '<label><input type="checkbox" name="tax_included" '.(!empty($tenant['tax_included'])?'checked':'').'> Los precios del catálogo incluyen IVA</label><p>Esta opción afecta nuevos consumos. Las cuentas abiertas conservan los importes ya registrados. Las opciones propias de cada sucursal tienen prioridad sobre los pagos y entregas generales.</p>';
    if($branch)echo '<label>Pedidos web · '.e($branch['name']).'<select class="input" name="web_order_acceptance"><option value="1" '.($branch['web_order_acceptance']?'selected':'').'>Requieren recibir / aceptar</option><option value="0" '.(!$branch['web_order_acceptance']?'selected':'').'>Recibir y enviar comanda automáticamente</option></select></label><p>La opción se aplica a pedidos nuevos de esta sucursal. La impresión usa el equipo y los perfiles elegidos en Impresión.</p>';
    echo '<button class="btn">Guardar datos</button> <a class="btn btn-light" href="'.e(url('admin/contenido')).'">Colores y diseño público</a></form></section>';admin_shell_end();
}
function qa180_design_sections():array {return [
    'portada'=>['Portada',['hero_title','hero_text'],['hero_image']],
    'nosotros'=>['Nosotros',['about_title','about_text'],['about_image']],
    'servicios'=>['Productos y servicios',['services_title','service_1_title','service_1_text','service_2_title','service_2_text','service_3_title','service_3_text'],['service_1_image','service_2_image','service_3_image']],
    'contacto'=>['Contacto',['contact_title','contact_text'],[]],
];}
function qa180_design(App $app,array $user,array $tenant):void {
    $tid=(int)$tenant['id'];$fields=r2_landing_fields()+['hero_button_label'=>'Botón principal','catalog_button_label'=>'Botones de catálogo / menú'];
    if(is_post()){
        verify_csrf();try {
            qa180_permission($app,$user,'contenido','write');$colors=[];foreach(['primary_color','accent_color'] as $field){$colors[]=(string)($_POST[$field]??$tenant[$field]);if(!preg_match('/^#[0-9a-fA-F]{6}$/D',end($colors)))throw new DomainException('Selecciona colores válidos.');}
            $images=[];foreach(qa180_design_sections() as [,$unused,$keys])foreach($keys as $key){if(isset($_POST['clear_'.$key]))$images[$key]='';elseif($image=upload_image($key))$images[$key]=$image;}
            $app->db->beginTransaction();$app->one('SELECT id FROM tenants WHERE id=? FOR UPDATE',[$tid]);foreach($fields as $key=>$label)r2_set($app,$tid,$key,mb_substr(trim((string)($_POST[$key]??'')),0,str_ends_with($key,'label')?80:3000));foreach($images as $key=>$image)r2_set($app,$tid,$key,$image);$app->exec('UPDATE tenants SET primary_color=?,accent_color=? WHERE id=?',[...$colors,$tid]);qa180_audit($app,$user,'business_design','tenant',$tid,'Guardó el diseño de la página y el catálogo del negocio');$app->db->commit();flash('success','Diseño guardado. La vista previa muestra la página publicada.');
        }catch(Throwable $error){if($app->db->inTransaction())$app->db->rollBack();flash('error',$error instanceof PDOException?'No se guardó el diseño.':$error->getMessage());}redirect(url('admin/contenido'));
    }
    admin_shell_start('Diseño del negocio',$user,$tenant,'contenido');echo '<p>Abre una sección, cambia sus textos o imágenes y guarda. Los colores se aplican a tu página y catálogo; el panel de administración mantiene su estilo.</p><div class="qa180-design"><form class="card admin-card" method="post" enctype="multipart/form-data">'.csrf_field();
    foreach(qa180_design_sections() as $id=>[$label,$keys,$images]){echo '<details class="qa180-design-section" '.($id==='portada'?'open':'').'><summary>'.e($label).'</summary>';foreach($keys as $key)echo '<label>'.e($fields[$key]).'<textarea class="input" name="'.$key.'" rows="2" maxlength="3000">'.e(r2_setting($app,$tid,$key)).'</textarea></label>';foreach($images as $key){$image=r2_setting($app,$tid,$key);echo '<label>Imagen'.($image?'<img class="r2-editor-image" src="'.e(public_media_url($image)).'" alt="Imagen actual">':'').'<input class="input" type="file" name="'.$key.'" accept="image/jpeg,image/png,image/webp"></label><label><input type="checkbox" name="clear_'.$key.'"> Quitar imagen</label>';}echo '</details>';}
    echo '<details class="qa180-design-section"><summary>Colores y botones</summary>';foreach(['primary_color'=>'Color principal','accent_color'=>'Color de acento'] as $key=>$label)echo field($label,$key,$tenant[$key],true,'color');foreach(['hero_button_label'=>'Ver catálogo o menú','catalog_button_label'=>'Ver catálogo completo →'] as $key=>$default)echo field($fields[$key],$key,r2_setting($app,$tid,$key,$default));echo '<a class="btn btn-light" target="_blank" rel="noopener" href="'.e(url($tenant['slug'].'/'.catalog_segment($tenant))).'">Abrir catálogo / menú</a></details><button class="btn">Guardar diseño</button></form><aside class="card admin-card"><h2>Vista previa publicada</h2><p>Los cambios aparecen después de guardar.</p><a class="btn btn-light" target="_blank" rel="noopener" href="'.e(url($tenant['slug'])).'">Abrir página completa</a><iframe class="qa180-design-preview" title="Vista previa de la página de tu tienda" loading="lazy" src="'.e(url($tenant['slug'])).'"></iframe></aside></div>';admin_shell_end();
}
